#include <iostream>
#include <string>

struct Data {
    int ival;  // An integer member
    std::string s;  // A string member
};

int main() {
    // Individual assignment (less idiomatic)
    Data val1;
    val1.ival = 0;
    val1.s = std::string("Anna");

    // Aggregate initialization (preferred for aggregates)
    Data val2 = {0, "Anna"};

    std::cout << "val2.ival: " << val2.ival << std::endl;  // Outputs: val2.ival: 0
    std::cout << "val2.s: " << val2.s << std::endl;  // Outputs: val2.s: Anna
    return 0;
}
